// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  },
  global: {
    headers: {
      'x-client-info': 'cleanflow-web',
    },
  },
});

// Interceptor para logging automático de erros
const originalFrom = supabase.from.bind(supabase);

// @ts-expect-error - Sobrescrevendo para adicionar interceptor de erro mantendo tipagem original onde possível
supabase.from = function <T extends string & keyof Database['public']['Tables']>(table: T) {
  const query = originalFrom(table);
  const originalThen = query.then?.bind(query);

  if (originalThen) {
    query.then = ((onfulfilled?: any, onrejected?: any) => {
      return originalThen(
        (result: any) => {
          if (result.error) {
            Promise.resolve().then(async () => {
              try {
                await supabase.rpc('log_system_event', {
                  p_level: 'error',
                  p_message: `Database error on ${table}: ${result.error.message}`,
                  p_service: 'database',
                  p_metadata: {
                    table,
                    error: result.error,
                    code: result.error.code
                  }
                });
              } catch (e) {
                console.error('Failed to log error:', e);
              }
            });
          }
          return onfulfilled ? onfulfilled(result) : result;
        },
        onrejected
      );
    }) as any;
  }

  return query;
};